def _canonical(value):
    return json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")


def seed_prompt_profiles(apps, schema_editor):
    Field = apps.get_model("studio", "PromptFieldDefinition")
    Profile = apps.get_model("studio", "PromptProfileVersion")
    Rule = apps.get_model("studio", "PromptProfileFieldRule")

    definitions = {}
    for order, (key, label, category, value_type, default_value) in enumerate(
        FIELD_DEFINITIONS,
        start=10,
    ):
        definition, _ = Field.objects.update_or_create(
            key=key,
            defaults={
                "label": label,
                "category": category,
                "description": FIELD_GUIDANCE[key][0],
                "impact": FIELD_GUIDANCE[key][1],
                "value_type": value_type,
                "default_value": default_value,
                "value_options": [],
                "is_required": False,
                "is_active": True,
                "display_order": order,
            },
        )
        definitions[key] = definition

    specs = []
    h3_rules = (
        ("subject", "request.subject", "positive_prompt"),
        ("environment", "request.environment", "positive_prompt"),
        ("action", "request.action", "positive_prompt"),
        ("camera", "request.camera", "positive_prompt"),
        ("visual_style", "request.style", "positive_prompt"),
        ("dialogue", "shot.dialogue", "positive_prompt"),
        ("bgm_style", "request.bgm_style", "positive_prompt"),
        ("negative_constraints", "request.negative_constraints", "negative_prompt"),
    )
    for mode in H3_MODES:
        specs.append({
            "profile_key": f"minimax_h3.video.{mode.casefold()}",
            "name": f"MiniMax H3 {mode} 装配策略",
            "model_family": "minimax_h3",
            "operation": "video.generate",
            "mode": mode,
            "official_reference": "https://platform.minimax.io/docs/guides/video-generation",
            "rules": h3_rules,
        })
    specs.extend((
        {
            "profile_key": "sdxl.image.general",
            "name": "SDXL 通用图片装配策略",
            "model_family": "sdxl",
            "operation": "image.generate",
            "mode": "",
            "official_reference": "https://huggingface.co/docs/diffusers/main/api/pipelines/stable_diffusion/stable_diffusion_xl",
            "rules": (
                ("subject", "request.subject", "positive_prompt"),
                ("environment", "request.environment", "positive_prompt"),
                ("lighting", "request.lighting", "positive_prompt"),
                ("visual_style", "request.style", "positive_prompt"),
                ("composition", "request.composition", "positive_prompt"),
                ("color_palette", "request.color_palette", "positive_prompt"),
                ("negative_constraints", "request.negative_constraints", "negative_prompt"),
            ),
        },
        {
            "profile_key": "deepseek.script.generate",
            "name": "DeepSeek 剧本生成装配策略",
            "model_family": "deepseek",
            "operation": "script.generate",
            "mode": "",
            "official_reference": "https://api-docs.deepseek.com/api/create-chat-completion",
            "rules": (
                ("system_guidance", "definition.default", "system_instruction"),
                ("theme", "request.theme", "structured_input"),
                ("visual_style", "request.style", "structured_input"),
                ("language", "request.language", "structured_input"),
            ),
        },
        {
            "profile_key": "qwen.script.generate",
            "name": "Qwen 剧本生成装配策略",
            "model_family": "qwen",
            "operation": "script.generate",
            "mode": "",
            "official_reference": "https://qwen.readthedocs.io/en/stable/deployment/vllm.html",
            "rules": (
                ("system_guidance", "definition.default", "system_instruction"),
                ("theme", "request.theme", "structured_input"),
                ("visual_style", "request.style", "structured_input"),
                ("language", "request.language", "structured_input"),
            ),
        },
        {
            "profile_key": "deepseek.prompt.normalize",
            "name": "DeepSeek 提示词规范化装配策略",
            "model_family": "deepseek",
            "operation": "prompt.normalize",
            "mode": "",
            "official_reference": "https://api-docs.deepseek.com/guides/json_mode/",
            "rules": (
                ("system_guidance", "definition.default", "system_instruction"),
                ("language", "request.language", "structured_input"),
                ("narrative", "request.text", "structured_input"),
            ),
        },
        {
            "profile_key": "qwen.prompt.normalize",
            "name": "Qwen 提示词规范化装配策略",
            "model_family": "qwen",
            "operation": "prompt.normalize",
            "mode": "",
            "official_reference": "https://qwen.readthedocs.io/en/stable/deployment/vllm.html",
            "rules": (
                ("system_guidance", "definition.default", "system_instruction"),
                ("language", "request.language", "structured_input"),
                ("narrative", "request.text", "structured_input"),
            ),
        },
    ))

    for spec in specs:
        profile, _ = Profile.objects.update_or_create(
            profile_key=spec["profile_key"],
            version=1,
            defaults={
                "name": spec["name"],
                "description": "内置初始策略，仅作为待审核草稿；管理员核对模型官方文档与本地合同后才能标记 ready 并发布。",
                "model_family": spec["model_family"],
                "operation": spec["operation"],
                "mode": spec["mode"],
                "official_reference": spec["official_reference"],
                "status": "draft",
                "review_state": "needs_review",
            },
        )
        Rule.objects.filter(profile_version=profile).delete()
        for position, (field_key, selector, channel) in enumerate(spec["rules"], start=1):
            Rule.objects.create(
                profile_version=profile,
                field_definition=definitions[field_key],
                source_selector=selector,
                channel=channel,
                position=position,
                label_style="label_colon",
                separator="newline",
                required=False,
                omit_if_empty=True,
                max_chars=30_000 if field_key in {"narrative", "system_guidance"} else 4_000,
            )
        rules = []
        for rule in Rule.objects.filter(profile_version=profile).select_related(
            "field_definition",
        ).order_by("position", "id"):
            definition = rule.field_definition
            rules.append({
                "field_key": definition.key,
                "field_value_type": definition.value_type,
                "field_default_value": definition.default_value,
                "field_value_options": definition.value_options,
                "field_required": definition.is_required,
                "source_selector": rule.source_selector,
                "channel": rule.channel,
                "position": rule.position,
                "label_style": rule.label_style,
                "separator": rule.separator,
                "required": rule.required,
                "omit_if_empty": rule.omit_if_empty,
                "max_chars": rule.max_chars,
            })
        payload = {
            "schema_version": 1,
            "profile_key": profile.profile_key,
            "version": profile.version,
            "model_family": profile.model_family,
            "operation": profile.operation,
            "mode": profile.mode,
            "rules": rules,
        }
        encoded = _canonical(payload)
        profile.contract_schema_version = 1
        profile.contract_size_bytes = len(encoded)
        profile.contract_sha256 = hashlib.sha256(encoded).hexdigest()
        profile.save(update_fields=(
            "contract_schema_version", "contract_size_bytes", "contract_sha256", "updated_at",
        ))


def unseed_prompt_profiles(apps, schema_editor):
    Profile = apps.get_model("studio", "PromptProfileVersion")
    Field = apps.get_model("studio", "PromptFieldDefinition")
    profile_keys = [f"minimax_h3.video.{mode.casefold()}" for mode in H3_MODES] + [
        "sdxl.image.general",
        "deepseek.script.generate",
        "qwen.script.generate",
        "deepseek.prompt.normalize",
        "qwen.prompt.normalize",
    ]
    Profile.objects.filter(profile_key__in=profile_keys, version=1).delete()
    Field.objects.filter(key__in=[item[0] for item in FIELD_DEFINITIONS]).delete()


